window.SHELF={"id": "surg", "name": "Surgery", "title": "Surgery Shelf Video Desk", "byline": "Dr High Yield \u00b7 Emma Holliday \u00b7 Divine Intervention", "hint": "Search a topic: tension pneumothorax, SBO, burns\u2026", "order": ["e", "h", "d"], "pdfs": [{"id": "divine", "short": "Divine Ep 24", "title": "Divine Intervention Episode 24 PDF", "file": "Divine%20Intervention%20Ep24.pdf", "pages": 118, "desc": "The 48 questions and topic slides he reads through in the episode."}, {"id": "mehlman", "short": "Mehlman HY Surgery", "title": "Mehlman Medical HY Surgery", "file": "https://drive.google.com/file/d/1NJSCz4w-XW7H_CNEY9Lqwfp3I6HO8i0K/view", "ext": true, "extNote": "Opens in Google Drive where you can download it.", "desc": "Mehlman free high-yield surgery document (opens in Google Drive)."}]};
window.VIDS=[{"key": "h", "id": "f7bhYONZgPY", "who": "Dr High Yield", "title": "High Yield Surgery Review", "len": 3298, "approx": false, "label": "H", "c": "h1", "short": "Dr High Yield", "rail": "Dr High Yield", "sections": [{"t": 28, "title": "Abdominal trauma: who goes to laparotomy", "notes": ["Gunshot below the nipple: **laparotomy**.", "Blunt or stab with peritonitis or unstable: **laparotomy**. Blunt + hypotensive, no peritonitis: **FAST**.", "Stable: **CT abdomen**."]}, {"t": 103, "title": "Tamponade vs tension pneumothorax", "notes": ["Tamponade: **Beck triad** (hypotension, JVD, muffled sounds), no respiratory distress. Pericardiocentesis.", "Tension: distress, **tracheal deviation**, absent breath sounds. **Needle decompression, then chest tube**.", "Trauma access: **2 large-bore IVs**."]}, {"t": 167, "title": "Head trauma, epidural hematoma, raised ICP", "notes": ["Loss of consciousness: **non-contrast head CT**. Normal and oriented: home.", "Epidural: **lens-shaped**, lucid interval. **Craniotomy**.", "High ICP: elevate head, brief hyperventilation, **mannitol**."]}, {"t": 232, "title": "Hemothorax and blunt chest trauma", "notes": ["Thoracotomy if **over 1.5 L** initial or **over 200 mL/h for 2 to 4 h**.", "Pulmonary contusion: white-out a day later, supportive. Myocardial contusion: sternal fracture, **ECG + troponin**.", "Aortic transection: deceleration, **widened mediastinum**, first rib fracture. **CT angiogram**."]}, {"t": 330, "title": "Genitourinary trauma", "notes": ["Bladder: **retrograde cystogram**. Intraperitoneal: surgery. Extraperitoneal: Foley.", "Kidney: lower rib fractures, hematuria, CT, usually conservative.", "Urethra: **blood at the meatus, high-riding prostate**. **Retrograde urethrogram before Foley**."]}, {"t": 386, "title": "Extremity vascular injury", "notes": ["Hard signs (expanding hematoma, pulsatile bleeding, no pulse): **OR**.", "Soft signs: **ankle-brachial index or Doppler**, CT angiogram."]}, {"t": 409, "title": "Pediatric orthopedics", "notes": ["DDH: clunk, asymmetric folds. **Ultrasound** (under 4 to 6 months), **Pavlik harness**.", "SCFE: obese 11 to 13 year old, knee or hip pain. **Surgical pinning**, no weight bearing.", "Bowlegs normal to 2 to 3, knock knees to 7 to 8: **reassure**.", "Legg-Calve-Perthes: 4 to 8, avascular necrosis. Osgood-Schlatter: tibial tubercle, conservative.", "Tibial stress fracture: normal x-ray, rest, repeat imaging."]}, {"t": 515, "title": "Compartment syndrome", "notes": ["After fractures (**supracondylar, tibia**), reperfusion, crush, tight cast.", "**Pain out of proportion, pain with passive stretch**. Pulses can be present.", "Measure pressure if unsure. **Fasciotomy**. Pain under a cast: **remove the cast**."]}, {"t": 604, "title": "Hand and wrist injuries", "notes": ["De Quervain: **Finkelstein test**. Splint, steroid injection.", "Gamekeeper thumb: ulnar collateral ligament. Mallet finger: extensor tear at the DIP, **splint in extension**. Jersey finger: flexor profundus avulsion, surgery."]}, {"t": 670, "title": "Cauda equina, Marjolin ulcer, gout", "notes": ["Cauda equina: **saddle anesthesia, retention, low anal tone**. **Emergency MRI**, decompression.", "Chronic non-healing wound or burn scar: **Marjolin ulcer (squamous cell)**, biopsy.", "Gout: **aspirate first**, negative birefringent needles. NSAID or colchicine, steroids in kidney disease. Allopurinol later."]}, {"t": 756, "title": "Knee injuries", "notes": ["Popping, clicking, locking: **meniscus**.", "Pop + rapid swelling (hemarthrosis): **ACL**, anterior drawer and **Lachman**. MRI."]}, {"t": 792, "title": "Preoperative risk", "notes": ["Avoid elective surgery: **EF under 35%**, DKA, recent MI (wait 6 months by the video, 60 days in current guidance).", "Stop smoking **8 weeks** before surgery."]}, {"t": 817, "title": "Malignant hyperthermia vs NMS vs serotonin syndrome", "notes": ["Malignant hyperthermia: **after inhaled anesthetic or succinylcholine**, rigidity, high CO2. **Dantrolene**.", "NMS: antipsychotic, lead-pipe rigidity, slow. Dantrolene or bromocriptine.", "Serotonin syndrome: serotonergic drugs, **clonus, hyperreflexia**. Benzodiazepines, cyproheptadine."]}, {"t": 871, "title": "Post-op problems: IVC filter, confusion, low urine", "notes": ["Clot with anticoagulation failure or contraindication: **IVC filter**.", "Post-op confusion: **check oxygen first**.", "Low urine output: **bladder scan**. Empty: fluids. Full: retention, catheterize."]}, {"t": 934, "title": "Ileus vs Ogilvie syndrome", "notes": ["Ileus: small and large bowel dilated, **low potassium worsens it**. Bowel rest, fix electrolytes.", "Ogilvie: **colon only** dilated. Neostigmine or **colonoscopic decompression**."]}, {"t": 973, "title": "Wound dehiscence, evisceration, infection, fistula", "notes": ["Dehiscence: **salmon-coloured drainage**. Bind, OR.", "Evisceration: **saline-soaked dressing, OR now**.", "Infection: open, irrigate, antibiotics, heal by secondary intention.", "Enterocutaneous fistula: green drainage. **Fluids, electrolytes, nutrition**."]}, {"t": 1076, "title": "Dysphagia and GI workup", "notes": ["Dysphagia: **barium swallow first**. Older with **weight loss or anemia: endoscopy**.", "Older with iron deficiency: **colonoscopy**."]}, {"t": 1132, "title": "Mallory-Weiss vs Boerhaave", "notes": ["Mallory-Weiss: mucosal tear after vomiting, hematemesis. Endoscopy.", "Boerhaave: **transmural**, pneumomediastinum, crepitus. **Water-soluble contrast (Gastrografin)**, surgery. Most common cause now: **endoscopy**."]}, {"t": 1229, "title": "H pylori, ulcers and small bowel obstruction", "notes": ["H pylori: gastric adenocarcinoma and **MALT lymphoma** (regresses with eradication). Ulcers: **NSAIDs and H pylori**.", "SBO: **adhesions and hernias**. X-ray: dilated loops, air-fluid levels. **NG tube, NPO, fluids**. Strangulation (fever, tachycardia, leukocytosis): **surgery now**."]}, {"t": 1322, "title": "C difficile and anal fissure", "notes": ["C diff: antibiotics, diarrhea, fever. Stool toxin. **Oral vancomycin** or fidaxomicin. Toxic megacolon.", "Anal fissure: **posterior midline**. Sitz baths, fibre, **topical nitroglycerin or diltiazem**."]}, {"t": 1388, "title": "Colicky vs peritonitic pain, mesenteric ischemia", "notes": ["Colic (biliary, renal): writhing. Perforation: **lies still, rigid**.", "Mesenteric ischemia: **pain out of proportion to exam**, AFib or atherosclerosis. **CT angiogram**."]}, {"t": 1462, "title": "Liver abscesses", "notes": ["Pyogenic: after cholangitis. **CT, percutaneous drainage**, antibiotics.", "Amebic: travel, diarrhea. **Metronidazole**, no drainage needed.", "Echinococcus: dogs, sheep, **eggshell calcification, daughter cysts**. Albendazole + surgery."]}, {"t": 1537, "title": "Biliary colic, cholecystitis, choledocholithiasis", "notes": ["Biliary colic: no fever. Elective cholecystectomy.", "Cholecystitis: fever, **Murphy sign**. **Ultrasound** (wall thickening, fluid, stones). Cholecystectomy within 72 h. Unclear: **HIDA scan**.", "Choledocholithiasis: **high ALP and bilirubin, CBD over 6 mm**. **ERCP**.", "Cholangitis: **Charcot** (fever, RUQ pain, jaundice), Reynolds (+ shock, confusion). Antibiotics + ERCP."]}, {"t": 1758, "title": "Pancreatitis and pseudocyst", "notes": ["Lipase 3 times normal + pain = diagnosis. First imaging: **RUQ ultrasound** for gallstones, not CT.", "Gallstone pancreatitis: **cholecystectomy same admission**.", "Pseudocyst at 4 to 6 weeks: early satiety. Drain if symptomatic (old rule: over 6 cm)."]}, {"t": 1860, "title": "Risk factors and pheochromocytoma", "notes": ["Breast cancer and osteoporosis: biggest risk is **age**. Stroke: **hypertension**.", "Pheo: **episodic hypertension, headache, sweating**. **Plasma or urine metanephrines**, then CT. **Alpha blocker before beta**."]}, {"t": 1902, "title": "Hernias", "notes": ["Direct: **medial to inferior epigastric**, older men, rarely incarcerates.", "Indirect: lateral, **patent processus vaginalis**, into scrotum.", "Femoral: women, **medial to femoral vein (NAVEL)**, most likely to incarcerate.", "Child umbilical hernia: **observe until 4 to 5 years**."]}, {"t": 2004, "title": "Acalculous cholecystitis", "notes": ["ICU, **TPN**, burns, sepsis. **Percutaneous cholecystostomy** if too sick for surgery."]}, {"t": 2027, "title": "Neonatal surgical emergencies", "notes": ["Congenital diaphragmatic hernia: bowel in left chest. **Intubate (no bag mask), stabilize, then surgery**.", "Malrotation with volvulus: **bilious vomiting**, upper GI series (corkscrew). Surgery.", "NEC: premature, **pneumatosis intestinalis**. NPO, antibiotics. Perforation: surgery."]}, {"t": 2116, "title": "Meconium ileus, intussusception, Meckel, Hirschsprung", "notes": ["Meconium ileus: **cystic fibrosis**. Gastrografin enema.", "Intussusception: **colicky pain, currant jelly stool**. **Air enema**.", "Meckel: **painless bleeding**, Meckel scan.", "Hirschsprung: no meconium, **tight sphincter, explosive stool**. **Rectal suction biopsy**. Down syndrome."]}, {"t": 2260, "title": "Undescended testis", "notes": ["**Orchiopexy by 6 to 12 months** (lowers infertility, not cancer risk, but allows exams)."]}, {"t": 2278, "title": "Stridor: vascular ring vs tracheomalacia", "notes": ["Vascular ring: stridor + **dysphagia**, better with neck extension.", "Tracheomalacia: **worse supine**, better prone, outgrown."]}, {"t": 2329, "title": "Valve surgery, CABG, lung nodules", "notes": ["Aortic stenosis: replace when **symptomatic** (angina, syncope, heart failure).", "CABG: **3-vessel disease, left main**, proximal LAD with diabetes.", "New nodule: **compare old films first**, then CT.", "Lung resection: post-op **FEV1 over 800 mL** (predicted)."]}, {"t": 2388, "title": "Aspiration pneumonia and lung abscess", "notes": ["Alcohol, seizures, stroke, dementia: **right lower lobe**, air-fluid level. **Clindamycin** or amoxicillin-clavulanate."]}, {"t": 2423, "title": "Subclavian steal", "notes": ["Dizziness with **arm exercise**, BP difference between arms. **Duplex**, stent or bypass."]}, {"t": 2486, "title": "AAA and peripheral artery disease", "notes": ["AAA: repair at **5.5 cm** (5 cm women), growth over 0.5 cm in 6 months, or symptoms. Screen **men 65 to 80 once** (Canada).", "PAD: claudication. **ABI under 0.9**. Exercise, aspirin, statin, smoking cessation. Rest pain or ABI under 0.4: revascularize."]}, {"t": 2556, "title": "Aortic dissection", "notes": ["Tearing pain to the back, widened mediastinum. **CT angiogram** (TEE if unstable or kidney failure).", "Type A (ascending): **surgery**. Type B: **beta blocker** first."]}, {"t": 2605, "title": "Skin cancer and eye emergencies", "notes": ["Basal cell: **pearly, telangiectasias**. Squamous: scaly ulcer, sun exposed.", "Infant strabismus: **correct early** to prevent amblyopia.", "Angle-closure glaucoma: painful red eye, halos, **mid-dilated fixed pupil**. Drops (timolol, pilocarpine), acetazolamide, **laser iridotomy**.", "Orbital (post-septal) cellulitis: **painful eye movements**, proptosis, vision loss. **CT**, IV antibiotics."]}, {"t": 2740, "title": "Head and neck cancer, foreign bodies", "notes": ["Smoker and drinker with hoarseness, mouth ulcer, one-sided earache: **squamous cell**. **Panendoscopy** (laryngoscopy, bronchoscopy, esophagoscopy).", "Child with one-sided foul discharge (nose, ear, vagina): **foreign body**."]}, {"t": 2797, "title": "TIA, carotid disease and stroke", "notes": ["Amaurosis fugax: **carotid emboli**. Symptomatic **70 to 99%** stenosis: **endarterectomy** (consider 50 to 69%).", "Stroke: **non-contrast CT** first. No bleed: thrombolysis. Bleed: control BP. SAH: **nimodipine** for vasospasm."]}, {"t": 2867, "title": "Pituitary and brain lesions", "notes": ["Prolactinoma: **cabergoline**.", "Acromegaly: **IGF-1** first, then glucose suppression test.", "Brain abscess: fever + focal signs, near ENT infection. **CT or MRI with contrast**, drain + antibiotics.", "Morning headache, vomiting: tumour, **MRI**."]}, {"t": 2945, "title": "Testicular torsion vs epididymitis", "notes": ["Torsion: sudden, **no cremasteric reflex**, high-riding. **Surgery now** (Doppler only if unsure), fix both sides.", "Epididymitis: gradual, fever, pyuria, **relief with elevation**. Young: **ceftriaxone + doxycycline**. Older: fluoroquinolone."]}, {"t": 3030, "title": "Obstructed infected stone, urethral valves, pneumaturia", "notes": ["Fever + obstructing stone: **emergency decompression** (nephrostomy or stent).", "Posterior urethral valves: newborn boy, cannot void. **VCUG**, catheter, ablation.", "Pneumaturia, fecaluria: **colovesical fistula**, diverticulitis or Crohn."]}, {"t": 3105, "title": "Transplant rejection", "notes": ["Hyperacute: **minutes**, preformed antibodies.", "Acute: weeks to months, T cells. **Steroids**.", "Chronic: years, fibrosis. Graft-versus-host: **rash, diarrhea, high LFTs** (systemic)."]}, {"t": 3193, "title": "Transfusion reactions by timing", "notes": ["Seconds: **anaphylaxis, IgA deficiency**. Epinephrine.", "Minutes: **ABO incompatibility**, flank pain, hemolysis. Stop transfusion, fluids.", "Hours: febrile nonhemolytic, cytokines. Leukoreduction.", "Days: **delayed hemolytic**, jaundice. TRALI: hypoxia within 6 h."]}]}, {"key": "e", "id": "d2GHmbblAb8", "who": "Emma Holliday", "title": "Surgery Shelf Review", "len": 7230, "approx": false, "label": "E", "c": "e", "short": "Emma Holliday", "rail": "Emma Holliday", "sections": [{"t": 114, "title": "Absolute contraindications and nutrition", "notes": ["**DKA** is an absolute contraindication to surgery.", "Poor nutrition: **albumin under 30 g/L**, transferrin under 200, **over 20% weight loss**. Delay elective surgery. **Enteral over TPN**.", "Liver failure: check bilirubin, **INR**, ammonia, encephalopathy."]}, {"t": 287, "title": "Smokers and oxygen after anesthesia", "notes": ["Stop smoking **8 weeks** before surgery (wound healing).", "COPD and CO2 retainers: **do not keep SpO2 at 100%** on waking (target 88 to 92%)."]}, {"t": 364, "title": "Goldman cardiac risk", "notes": ["Biggest risk: **heart failure** (JVD, S3). Get an echo. **EF under 35%**: avoid elective surgery.", "Second: **MI within 6 months**. ECG for older patients. Abnormal: stress test, then cath.", "Also: arrhythmia, age over 70, emergency surgery, **aortic stenosis**."]}, {"t": 578, "title": "Medications to stop before surgery", "notes": ["**Aspirin and NSAIDs 7 to 10 days**, vitamin E. Warfarin: aim **INR under 1.5**.", "**Metformin** (lactic acidosis). Insulin: **half the morning dose** when NPO.", "Dialysis **within 24 h before**. Uremia: **platelet dysfunction** with normal count, long bleeding time."]}, {"t": 733, "title": "Ventilator settings", "notes": ["Assist control: set volume and rate. **Pressure support: weaning**.", "CPAP: needs own drive. **PEEP: keeps alveoli open (ARDS)**.", "ABG: low PaO2, raise FiO2 or PEEP. **Too much O2: free radical injury**.", "CO2 problems: adjust **tidal volume** (less dead space) or rate."]}, {"t": 1078, "title": "Acid-base approach", "notes": ["pH, then HCO3 and PCO2 to find the primary problem.", "Metabolic acidosis: **anion gap** (Na minus Cl minus HCO3, normal 8 to 12). **MUDPILES**. Normal gap: **diarrhea**, RTA.", "Metabolic alkalosis: **urine chloride**. Low: vomiting. High: hyperaldosteronism, Bartter, Gitelman."]}, {"t": 1366, "title": "Hyponatremia", "notes": ["Check **serum osmolality** (rule out hyperglycemia), then **volume status**.", "Hypervolemic: heart failure, cirrhosis, nephrotic. Hypovolemic: diuretics, vomiting (**give saline**). Euvolemic: **SIADH** (chest x-ray in a smoker).", "**Hypertonic saline** only for seizures, coma or very low sodium. Correct **no more than 8 to 10 mmol/L per day** (osmotic demyelination).", "Hypernatremia: free water slowly (cerebral edema)."]}, {"t": 1636, "title": "Calcium and potassium", "notes": ["Low calcium: perioral numbness, **Chvostek and Trousseau**, long QT. High: stones, bones, groans, psych overtones, short QT.", "Low potassium: ileus, weakness, **U waves**. Replace, check kidney function.", "High potassium: peaked T, wide QRS. **Calcium gluconate first**, then insulin + glucose, salbutamol, then remove (binders, dialysis)."]}, {"t": 1775, "title": "Maintenance fluids and nutrition", "notes": ["Maintenance: **D5 half normal saline + 20 mmol KCl** once voiding.", "**4-2-1 rule** (or 100/50/20 mL/kg/day).", "Enteral beats parenteral. TPN only if the gut cannot be used."]}, {"t": 1837, "title": "Burns: depth, airway, carbon monoxide", "notes": ["First degree: epidermis, red, painful. Second: blisters, very painful. **Third: full thickness, painless**.", "Circumferential burns: **escharotomy** (compartment syndrome, restricted breathing).", "Singed nasal hair, soot, wheeze: **inhalation injury, intubate early**.", "Headache, confusion after fire: **carbon monoxide**. Pulse ox is falsely normal. **Carboxyhemoglobin, 100% O2**, hyperbaric if severe."]}, {"t": 1980, "title": "Clotting and bleeding disorders in surgical patients", "notes": ["Older with new clots: **cancer**. Edema + foamy urine: **nephrotic** (antithrombin loss).", "Young with family history: **factor V Leiden**. Antithrombin deficiency: **heparin does not work**.", "Recurrent miscarriage: antiphospholipid. **Low platelets + new clots on heparin: HIT** (stop heparin, argatroban).", "Low platelets alone: ITP. Normal platelets, long bleeding time and PTT: **von Willebrand**. Everything off, schistocytes: **DIC** (gram-negative sepsis)."]}, {"t": 2248, "title": "Burn fluids and topical agents", "notes": ["**Parkland: 4 mL x kg x % TBSA** (2 mL in some sources), **half in first 8 h**. Rule of nines (kids: bigger head).", "No systemic antibiotics. Topicals: **silver sulfadiazine** (leukopenia, poor eschar penetration), **mafenide** (penetrates, painful, acidosis), **silver nitrate** (low Na and K)."]}, {"t": 2371, "title": "Chemical and electrical burns, rhabdo", "notes": ["Chemical: **irrigate**, especially eyes.", "Electrical: **ECG first**, telemetry if abnormal. Deep damage is bigger than the skin shows.", "Dipstick blood with no RBCs: **rhabdomyolysis**. Check **potassium**, fluids.", "White, cold, pulseless burned limb: compartment syndrome (**over 30 mmHg**). Fasciotomy."]}, {"t": 2496, "title": "Trauma airway", "notes": ["Unconscious, **GCS 8 or less**, stridor from anaphylaxis, **expanding neck hematoma**: intubate.", "Neck crepitus (airway injury): **fibreoptic intubation**.", "Massive facial trauma: **cricothyroidotomy**.", "After intubation, listen. Decreased on the left: **right mainstem, pull back**."]}, {"t": 2622, "title": "Chest x-rays in trauma", "notes": ["Widened mediastinum after high-speed crash: **aortic injury**, urgent repair.", "Pneumothorax: hyperresonant, decreased sounds. Tension: JVD, **tracheal deviation away**.", "Hemothorax: dull. **Chest tube**. OR if **over 1.5 L initially or over 200 mL/h for 4 h**.", "Pulmonary contusion (white-out): **pulmonary toilet, pain control**, no surgery."]}, {"t": 2842, "title": "Flail chest, fat and air embolism", "notes": ["Flail chest: **paradoxical movement**, 3+ consecutive ribs broken in 2 places. Pain control with **nerve blocks** (avoid heavy opioids).", "Fat embolism: long bone fracture, **confusion, petechiae, hypoxia**.", "Air embolism: central line removal, lung trauma, ventilator."]}, {"t": 2942, "title": "Shock types, tamponade and tension pneumothorax", "notes": ["Hypotension + tachycardia + flat neck veins: **hypovolemic**. 2 large-bore IVs, crystalloid bolus, then blood.", "Tamponade: muffled sounds, JVD, **electrical alternans, pulsus paradoxus**. FAST, **pericardiocentesis**.", "Tension: **needle decompression without x-ray**, then chest tube.", "Neurogenic shock (spinal cord): **hypotension with bradycardia**, warm skin."]}, {"t": 3100, "title": "Head trauma: GCS, bleeds, ICP", "notes": ["GCS: eyes 4, verbal 5, motor 6. Head trauma or LOC: **non-contrast CT**.", "Epidural: lens-shaped. Acute subdural: bright crescent. **Chronic subdural**: dark, elderly, falls, slow decline.", "Raised ICP: headache, vomiting, papilledema. **Head up 30, mannitol, brief hyperventilation (PCO2 30 to 35)**. Burr hole or ventriculostomy."]}, {"t": 3262, "title": "Penetrating neck trauma by zone", "notes": ["Zone 3 (above angle of mandible): **angiography + endoscopy**.", "Zone 2 (angle to cricoid): explore or CT angiogram.", "Zone 1 (below cricoid): **angiography**, aortic injury. Today most stable patients get **CT angiogram** first.", "Hard signs (expanding hematoma, bleeding, stridor): **OR**."]}, {"t": 3347, "title": "Penetrating and blunt abdominal trauma", "notes": ["Free air under diaphragm or **gunshot**: laparotomy + tetanus.", "Stab: unstable or peritonitis: **OR**. Stable: wound exploration, **FAST**, DPL.", "Blunt unstable: FAST, **OR if positive**. Stable: **CT**.", "Lower rib fracture + bleeding: spleen (left), liver (right). + hematuria: kidney."]}, {"t": 3479, "title": "Diaphragm, pancreas and duodenal injuries", "notes": ["**Kehr sign** (left shoulder pain): splenic injury. Bowel in chest: **diaphragm rupture**.", "**Handlebar injury**: pancreatic injury.", "Retroperitoneal air or fluid on CT after epigastric blow: **duodenal rupture**."]}, {"t": 3570, "title": "Pelvic and urethral trauma", "notes": ["Unstable pelvic fracture: **pelvic binder**, angioembolization.", "Blood at meatus, high-riding prostate: **retrograde urethrogram, no Foley**.", "Normal urethra: **retrograde cystogram** (2 views). Extraperitoneal: Foley. **Intraperitoneal: surgery**."]}, {"t": 3662, "title": "Orthopedic trauma", "notes": ["To the OR: **depressed skull fracture**, severe displacement, **open fracture**, femoral neck and intertrochanteric.", "Shoulder pain after seizure or electrocution: **posterior dislocation**. Anterior: **axillary nerve** (deltoid numbness).", "FOOSH older: **Colles (dinner fork)**. Young with snuffbox tenderness: **scaphoid**, x-ray can be negative, **splint and re-image**.", "Punch: **boxer fracture** (5th metacarpal neck). Clavicle: middle third."]}, {"t": 3827, "title": "Post-op fever: day 1 and beyond", "notes": ["Day 1: **atelectasis** (incentive spirometer, ambulate). Very high fever + pain: **necrotizing fasciitis** (strep, Clostridium). **Debride in OR + IV antibiotics**.", "Malignant hyperthermia in PACU: halothane or succinylcholine, **ryanodine receptor**. **Dantrolene**.", "Days 3 to 5: **pneumonia, UTI** (culture, remove Foley).", "Day 7+: **line infection** (cultures, pull line), cellulitis, **wound infection** (open, pack), dehiscence (salmon fluid, OR), **abscess** (CT, drain).", "Unexplained fever after pelvic surgery: **septic pelvic thrombophlebitis**. Antibiotics + heparin."]}, {"t": 4213, "title": "Pressure ulcers", "notes": ["Stage 1: **nonblanching** redness. 2: partial thickness. 3: into fat. 4: muscle, bone.", "Non-healing chronic ulcer: **Marjolin (squamous cell)**, biopsy.", "Stage 1 to 2: offload, dressings. 3 to 4: **debridement, flap**."]}, {"t": 4286, "title": "Pleural effusion and Light criteria", "notes": ["Over 1 cm on decubitus: **thoracentesis**.", "Transudate: heart failure, nephrotic, cirrhosis. Exudate: **pneumonia, cancer**, TB (lymphocytes), PE (bloody).", "Complicated (low pH, **low glucose**, organisms): **chest tube**.", "Light: protein ratio **over 0.5**, LDH ratio **over 0.6**."]}, {"t": 4386, "title": "Spontaneous pneumothorax and lung abscess", "notes": ["Tall thin young man or COPD bleb. Chest x-ray. Small: observe or aspirate. Large: **chest tube**.", "Surgery (VATS bleb resection, pleurodesis): **recurrence, bilateral, persistent leak, pilots or divers**.", "Lung abscess: air-fluid level. **Antibiotics first** (clindamycin, amoxicillin-clavulanate). Drain only if failing or empyema."]}, {"t": 4480, "title": "Solitary pulmonary nodule", "notes": ["**Compare with old films** first.", "Benign: **popcorn (hamartoma)**, concentric calcification (granuloma), stable 2 years, young.", "Suspicious: large, **spiculated**, older smoker. Biopsy (bronchoscopy if central, CT-guided or surgical if peripheral)."]}, {"t": 4545, "title": "Lung cancer types", "notes": ["Adenocarcinoma: **non-smokers, peripheral**, scar. Mets: liver, bone, brain, **adrenals**.", "Squamous: **central, PTHrP hypercalcemia**, Pancoast.", "Small cell: central, **SIADH, Lambert-Eaton**, Cushing. **Chemo and radiation, not surgery**.", "Large cell: peripheral, cavitating.", "Pancoast: shoulder pain + **Horner** + SVC."]}, {"t": 4786, "title": "ARDS", "notes": ["Causes: **sepsis, aspiration, pancreatitis**, trauma, transfusion.", "Criteria: bilateral infiltrates, **PaO2/FiO2 under 300**, not cardiac.", "Treat: **low tidal volume ventilation, PEEP**, prone positioning."]}, {"t": 4868, "title": "Murmurs: AS vs HOCM", "notes": ["Aortic stenosis: crescendo-decrescendo, **softer with Valsalva**, slow pulse.", "HOCM: **louder with Valsalva and standing**, softer with squat and handgrip."]}, {"t": 4931, "title": "Systolic, diastolic and congenital murmurs", "notes": ["MVP: **mid-systolic click**. MR: holosystolic to the axilla.", "VSD: holosystolic, most common congenital. PDA: **machine-like**. ASD: **fixed split S2**.", "Mitral stenosis: **opening snap**, rumble. Aortic regurgitation: blowing diastolic, wide pulse pressure.", "Right-sided murmurs: **louder with inspiration**."]}, {"t": 5043, "title": "Esophagus: Zenker, achalasia, spasm, GERD", "notes": ["Zenker: **halitosis, regurgitating old food**. False diverticulum. Surgery.", "Achalasia: solids and liquids, **bird beak**. Manometry. Botox, dilation, **Heller myotomy** or POEM.", "Diffuse spasm: **corkscrew**, chest pain with hot or cold. CCBs, nitrates.", "GERD surgery (Nissen): complications (stricture, bleeding, Barrett) or **failed maximal medical therapy**."]}, {"t": 5173, "title": "Boerhaave and varices", "notes": ["Hematemesis after vomiting + **subcutaneous emphysema, effusion**: Boerhaave. Chest x-ray, **water-soluble contrast**, repair.", "Variceal bleed: resuscitate, **octreotide, antibiotics, band ligation**. Balloon tamponade as a bridge.", "Prevention of first bleed: **non-selective beta blocker** or banding of large varices."]}, {"t": 5286, "title": "Esophageal cancer", "notes": ["Progressive dysphagia (solids then liquids) + weight loss.", "Squamous: upper and middle, **smoking and alcohol**. Adenocarcinoma: lower, **Barrett**.", "Barium swallow can start, but **endoscopy with biopsy** is the answer."]}, {"t": 5320, "title": "Hiatal hernia and gastric ulcer", "notes": ["Type 1 sliding: treat reflux. **Type 2 paraesophageal: surgery** (strangulation risk).", "Gastric ulcer: **pain worse with eating**. NSAIDs, H pylori. **EGD with biopsy** (rule out cancer)."]}, {"t": 5408, "title": "Gastric cancer and lymphoma", "notes": ["Adenocarcinoma: Japanese, nitrates, H pylori. **Krukenberg** (ovary), Blumer shelf, **Virchow node** (left supraclavicular), **Sister Mary Joseph** (umbilicus).", "MALT lymphoma: **H pylori**, regresses with eradication.", "Menetrier: enlarged rugae, **protein loss**. Gastric varices: **splenic vein thrombosis**. Dieulafoy: bleeding vessel."]}, {"t": 5523, "title": "Duodenal ulcer and Zollinger-Ellison", "notes": ["Duodenal: **pain better with eating**, H pylori. Test (urea breath, stool antigen, biopsy). **PPI + triple therapy**, confirm cure.", "Refractory or multiple ulcers, jejunal ulcers, diarrhea: **gastrinoma**. **High gastrin, secretin stimulation test**.", "Gastrinoma: pancreas or duodenum. Check **MEN1** (parathyroid, pituitary)."]}, {"t": 5664, "title": "SMA syndrome", "notes": ["**Rapid weight loss**, postprandial pain, bilious vomiting. Duodenum compressed between aorta and SMA.", "Restore nutrition, surgery last."]}, {"t": 5707, "title": "Pancreatitis and its complications", "notes": ["Epigastric pain **to the back**. **Gallstones and alcohol**. Lipase. Fluids, analgesia, early feeding.", "CT for severity or if diagnosis unclear, not routinely.", "Complications: **pseudocyst** (no epithelium), necrosis, abscess, hemorrhage, **ARDS**.", "Chronic: malabsorption, diabetes, **splenic vein thrombosis, gastric varices**."]}, {"t": 5824, "title": "Pancreatic cancer", "notes": ["Head tumours: painless jaundice, **Courvoisier sign** (palpable non-tender gallbladder). **Trousseau** migratory thrombophlebitis.", "CT pancreas protocol, **endoscopic ultrasound with FNA**. CA 19-9.", "Resectable: **no distant mets, no SMA or portal vein encasement**. Whipple."]}, {"t": 5929, "title": "Pancreatic endocrine tumours", "notes": ["Insulinoma: **Whipple triad**. High insulin, **high C-peptide and proinsulin**. Factitious insulin: low C-peptide.", "Glucagonoma: diabetes, weight loss, **necrolytic migratory erythema**.", "Somatostatinoma: gallstones, diabetes, steatorrhea. VIPoma: **watery diarrhea, low K**, achlorhydria. **Octreotide**."]}, {"t": 6031, "title": "Gallbladder and bile ducts", "notes": ["Biliary colic vs cholecystitis: **fever and high WBC** mean cholecystitis. **Ultrasound first**. Cholecystectomy. Too sick: **percutaneous cholecystostomy**.", "High bilirubin and ALP: **choledocholithiasis**, ERCP.", "**Reynolds pentad** (+ shock, confusion): cholangitis. Antibiotics + urgent ERCP.", "Choledochal cyst type 1: excision. Type 4 or Caroli: liver transplant. Cholangiocarcinoma: **PSC**."]}, {"t": 6208, "title": "Liver enzymes, cirrhosis, HCC", "notes": ["AST:ALT over 2: **alcohol**. Thousands with ALT higher: **viral**. Thousands after hypotension: **shock liver**.", "Portal hypertension: octreotide. **TIPS** lowers pressure but **worsens encephalopathy**. Encephalopathy: **lactulose**.", "HCC: **hep B carriers**, hep C, cirrhosis. **AFP**, CT or MRI."]}, {"t": 6369, "title": "Benign liver tumours", "notes": ["Woman on OCPs, mass or **rupture with shock**: **hepatic adenoma**. Stop OCPs. Resect if large or planning pregnancy.", "Hemangioma: most common, leave alone. **FNH: central scar**, leave alone."]}, {"t": 6446, "title": "Liver abscesses and hydatid cyst", "notes": ["Bacterial: **E coli, Bacteroides, Enterococcus**. Drain + IV antibiotics.", "Amebic: very sick, travel. **Metronidazole, no drainage**.", "Echinococcus: dogs, sheep, **eosinophilia**, eggshell cyst. Albendazole + **careful whole-cyst removal** (anaphylaxis if spilled)."]}, {"t": 6600, "title": "Spleen", "notes": ["After splenectomy: **thrombocytosis**. Vaccines: **pneumococcus, meningococcus, Hib**. Penicillin prophylaxis in children.", "ITP: isolated low platelets. Hereditary spherocytosis: splenomegaly, **splenectomy**.", "Splenic rupture: left lower rib fracture, **Kehr sign**."]}, {"t": 6679, "title": "Appendicitis and carcinoid", "notes": ["Periumbilical pain moving to RLQ. Strong clinical picture: **surgery** (CT or ultrasound often done).", "Abscess or perforation with phlegmon: **drain + antibiotics, interval appendectomy**.", "Carcinoid: most common in the **appendix**. Syndrome (flushing, diarrhea, wheeze) means **liver mets**. **Niacin deficiency** (pellagra).", "Over 2 cm, base, or nodes: **right hemicolectomy**. Under 2 cm at tip: appendectomy."]}, {"t": 6884, "title": "SBO, ileus, Ogilvie", "notes": ["SBO surgery: **peritoneal signs** or no improvement in **48 h**.", "Ileus: gas throughout small and large bowel. **Check potassium**.", "Ogilvie: huge **cecum**. Decompress if **over 10 to 12 cm**: **neostigmine** (bradycardia, monitor), colonoscopic decompression."]}, {"t": 6992, "title": "Abdominal x-ray patterns", "notes": ["**Plicae across the whole lumen**: small bowel. Haustra partway: colon.", "Free air under the diaphragm: **OR**.", "**Coffee bean**: sigmoid volvulus (sigmoidoscopic detorsion). Bird beak on contrast or ectopic gas-filled loop: **cecal volvulus** (surgery)."]}]}, {"key": "d", "id": "Vx39Q5ZC7VQ", "who": "Divine Intervention", "title": "Episode 24: Comprehensive Surgery Shelf Review", "len": 8399, "approx": true, "label": "D", "c": "d", "short": "Divine Ep 24", "rail": "Divine Intervention Ep 24", "sections": [{"t": 60, "title": "How to approach the surgery shelf", "notes": ["Lots of medicine with a surgical angle. **UWorld + NBME forms**.", "Pick the simple answer with the most evidence."], "p": 2}, {"t": 202, "title": "CABG, coronary territories and pericarditis", "notes": ["Left main or 3-vessel disease: **CABG**, internal mammary graft lasts longest.", "II, III, aVF: **RCA** (avoid nitrates, preload dependent). V1 to V4: LAD. I, aVL, V5 to V6: circumflex.", "Early post-cardiac surgery pericarditis vs weeks later **Dressler** (autoimmune)."], "p": 4}, {"t": 415, "title": "Endocarditis", "notes": ["**Echo + blood cultures** (TTE first).", "IV drug use: **tricuspid, S aureus**. Strep gallolyticus (bovis): **colonoscopy**. After dental work: viridans."], "p": 7}, {"t": 557, "title": "Leg pain: venous vs arterial", "notes": ["Varicose veins: **better with elevation**, worse standing. Incompetent valves. Compression stockings.", "PAD: claudication, **worse with elevation**, smoker. ABI."], "p": 9}, {"t": 700, "title": "Malignant hyperthermia", "notes": ["Halothane or **succinylcholine**: hyperthermia, rigidity, **high end-tidal CO2**, hyperkalemia.", "Autosomal dominant, **ryanodine receptor**. **Dantrolene**."], "p": 11}, {"t": 842, "title": "Chronic and acute mesenteric ischemia", "notes": ["Chronic: **postprandial pain, food fear, weight loss**, atherosclerosis.", "Acute: **AFib, pain out of proportion**. **CT angiogram**."], "p": 13}, {"t": 984, "title": "Secondary hypertension", "notes": ["Older + bruit: **renal artery stenosis** (atherosclerosis). Young woman: **fibromuscular dysplasia**.", "Low K, alkalosis, **low renin**: hyperaldosteronism (aldosterone:renin ratio).", "Buffalo hump, striae: Cushing. Episodic headache, sweating: **pheochromocytoma**. Coarctation, OSA, hyperthyroidism."], "p": 15}, {"t": 1126, "title": "AAA screening and repair", "notes": ["**Men 65 to 80**, one ultrasound (Canada: all men, US: ever smokers).", "Repair at **5.5 cm** (5 cm in women), growth over 0.5 cm in 6 months, or symptoms. Smaller: surveillance.", "Rupture: pain to back, hypotension, pulsatile mass: **straight to OR**."], "p": 17}, {"t": 1268, "title": "Postoperative urinary retention", "notes": ["Suprapubic fullness, low urine output after surgery: **bladder catheter** first."], "p": 19}, {"t": 1411, "title": "Testicular torsion and other scrotal masses", "notes": ["Torsion: **no cremasteric reflex**. **Surgical detorsion + bilateral orchiopexy**.", "Epididymitis: positive Prehn, pyuria.", "Hydrocele: **transilluminates**. Varicocele: bag of worms, **left side**, worse standing. Right-sided or not reducing lying down: **renal mass**.", "Testicular cancer: firm painless mass. **Ultrasound, tumour markers, radical inguinal orchiectomy** (never trans-scrotal biopsy)."], "p": 21}, {"t": 1624, "title": "Epidural hematoma", "notes": ["Temporal bone fracture, **middle meningeal artery**, lucid interval, **lens-shaped**.", "**Non-contrast head CT** first. Craniotomy."], "p": 24}, {"t": 1766, "title": "Colonic perforation after endoscopy", "notes": ["New abdominal pain, fever or hypotension after colonoscopy or dilation: **perforation**. Upright x-ray or CT, surgery."], "p": 26}, {"t": 1908, "title": "Acute limb ischemia", "notes": ["Recent MI or **AFib** + sudden cold pale pulseless limb: **embolus**.", "**Heparin immediately**, then embolectomy or thrombolysis. 6 Ps. After revascularization: watch for **compartment syndrome**."], "p": 28}, {"t": 2051, "title": "Aortoenteric fistula", "notes": ["Prior **AAA graft** + GI bleeding (herald bleed, positive FOBT, anemia): aortoenteric fistula. CT angiogram, surgery."], "p": 30}, {"t": 2193, "title": "Risk factors for big diseases", "notes": ["**Smoking**: strongest risk for atherosclerosis, AAA, PAD.", "**Hypertension**: strongest risk for stroke and dissection."], "p": 32}, {"t": 2335, "title": "Upper limb nerve injuries", "notes": ["Midshaft humerus: **radial nerve** (wrist drop).", "Medial epicondyle, elbow dislocation: **ulnar** (claw hand, can not spread fingers).", "Supracondylar fracture, carpal tunnel: **median** (thenar, opposition).", "Surgical neck of humerus, anterior dislocation: **axillary** (deltoid).", "Long thoracic: winged scapula after mastectomy."], "p": 34}, {"t": 2548, "title": "Neck masses", "notes": ["Lateral, anterior to SCM: **branchial cleft cyst** (pharyngeal cleft, ectoderm).", "Midline, **moves with swallowing or tongue protrusion**: thyroglossal duct cyst. Sistrunk procedure.", "Posterior triangle, transilluminates: **cystic hygroma** (Turner)."], "p": 37}, {"t": 2762, "title": "Heparin-induced thrombocytopenia", "notes": ["Platelets drop **over 50% about 5 to 10 days** after heparin + new clots.", "Stop all heparin (including flushes, LMWH). **Argatroban** or a DOAC. No platelet transfusion."], "p": 40}, {"t": 2904, "title": "Bleeding disorders", "notes": ["Platelet problems: mucosal bleeding, petechiae. Factor problems: deep joint and muscle bleeds.", "von Willebrand: long bleeding time, maybe long PTT. **Desmopressin**. Hemophilia: long PTT only.", "Uremia: platelet dysfunction, desmopressin. Vitamin K: long PT first."], "p": 42}, {"t": 3046, "title": "Rapid fire triggers", "notes": ["**Monteggia**: proximal ulna + radial head dislocation. **Galeazzi**: distal radius + DRUJ dislocation.", "Meckel: **rule of 2s**, painless bleeding, technetium scan.", "Ventilated + sudden hypotension, absent breath sounds: **tension pneumothorax**. Needle (2nd ICS midclavicular or 4th to 5th ICS midaxillary), then chest tube."], "p": 44}, {"t": 3188, "title": "Toxic megacolon and perforation", "notes": ["Ulcerative colitis or C diff + **colon over 6 cm**, fever, tachycardia.", "NG, steroids, antibiotics. **Peritonitis or perforation: laparotomy (colectomy)**."], "p": 46}, {"t": 3331, "title": "Cardiac tamponade", "notes": ["**Beck triad**, electrical alternans, pulsus paradoxus.", "Penetrating chest trauma: **pericardiocentesis as bridge, then sternotomy or thoracotomy**."], "p": 48}, {"t": 3473, "title": "Gallstone ileus", "notes": ["Elderly woman, **SBO + air in the biliary tree** (pneumobilia), stone in the ileum.", "Laparotomy, remove the stone. Vomiting: **hypochloremic hypokalemic metabolic alkalosis**."], "p": 50}, {"t": 3615, "title": "Appendicitis signs and imaging", "notes": ["**McBurney, Rovsing, obturator, psoas** signs.", "Imaging: **CT** in adults, **ultrasound in children and pregnancy** (then MRI)."], "p": 52}, {"t": 3757, "title": "Upper GI bleed patterns", "notes": ["Alcoholic, hematemesis, stable: **Mallory-Weiss**. + subcutaneous emphysema: **Boerhaave** (Gastrografin).", "Cirrhosis: varices (octreotide, antibiotics, banding). NSAIDs: ulcer (PPI, endoscopy)."], "p": 54}, {"t": 3900, "title": "Splenic rupture after mono", "notes": ["Infectious mononucleosis: **avoid contact sports 3 to 4 weeks** (splenic rupture).", "Asplenia: vaccinate for **pneumococcus, Hib, meningococcus**."], "p": 56}, {"t": 4042, "title": "Glasgow Coma Scale", "notes": ["Eyes 4, verbal 5, motor 6. Decerebrate posturing (extension) = motor 2.", "**GCS 8 or less: intubate**."], "p": 58}, {"t": 4184, "title": "Volvulus", "notes": ["**Sigmoid**: elderly, constipation, nursing home. **Coffee bean (omega)** sign. Sigmoidoscopic detorsion, then elective resection.", "Cecal: younger, surgery."], "p": 60}, {"t": 4326, "title": "Intussusception", "notes": ["6 months to 3 years, **colicky pain, currant jelly stool, sausage mass**, target sign on ultrasound.", "**Air or contrast enema** (diagnostic and therapeutic). Peritonitis: surgery. Lead points: Meckel, lymphoma. Rotavirus vaccine."], "p": 62}, {"t": 4468, "title": "Mixed surgical triggers", "notes": ["Tumour plop + TIA: **atrial myxoma**.", "Compartment syndrome: **fasciotomy**.", "Pearly mass behind the eardrum: **cholesteatoma**.", "SBO causes: **adhesions, hernias, cancer**. Hair-eating psych patient: bezoar."], "p": 64}, {"t": 4611, "title": "Best first test by scenario", "notes": ["Diverticulitis: **CT with contrast**. No colonoscopy acutely (wait 6 weeks).", "Lower GI bleed in elderly: **diverticulosis** (colonoscopy, tagged RBC scan or CT angiogram if brisk).", "Pneumaturia: colovesical fistula, **CT**.", "Appendicitis: CT adults, **ultrasound pregnant and kids**."], "p": 66}, {"t": 4753, "title": "Neonatal surgical emergencies", "notes": ["Premature + bloody stool + pneumatosis: **NEC**. Neutropenic adult: typhlitis.", "Drooling, choking at first feed, **NG coils**, polyhydramnios: **esophageal atresia with TEF**. Check **VACTERL**.", "**Projectile non-bilious vomiting** at 3 to 6 weeks, olive: **pyloric stenosis**. **Hypochloremic hypokalemic alkalosis**. Ultrasound, fix fluids first, pyloromyotomy."], "p": 68}, {"t": 4895, "title": "Bilious vomiting and obstruction in infants", "notes": ["Down syndrome + bilious vomiting day 1: **duodenal atresia** (double bubble).", "Any bilious vomiting: **malrotation with volvulus** until proven otherwise, upper GI series.", "No meconium + Down syndrome: **Hirschsprung** (suction rectal biopsy). Cystic fibrosis: meconium ileus."], "p": 70}, {"t": 5037, "title": "Knee injuries", "notes": ["ACL: **Lachman** (most sensitive), anterior drawer.", "Meniscus: **McMurray**, locking.", "Dashboard injury: **PCL**, posterior drawer. Valgus blow: MCL. Unhappy triad: ACL, MCL, medial meniscus."], "p": 72}, {"t": 5180, "title": "Short bowel and post-resection problems", "notes": ["Crohn after ileal resection: **B12 deficiency**, bile acid diarrhea, **oxalate kidney stones**, gallstones."], "p": 74}, {"t": 5322, "title": "Postoperative jaundice", "notes": ["Mild **indirect hyperbilirubinemia** after surgery, otherwise well: **Gilbert** (stress, fasting). Reassure."], "p": 76}, {"t": 5464, "title": "Ogilvie after major surgery", "notes": ["Massive colonic dilation without obstruction after major surgery or sepsis.", "Decompress: NG, rectal tube, correct electrolytes. **Neostigmine** if cecum over 10 to 12 cm. Colonoscopic decompression."], "p": 78}, {"t": 5606, "title": "Surgical signs", "notes": ["Periumbilical and flank bruising: **Cullen and Grey Turner**, hemorrhagic pancreatitis.", "Double bubble: duodenal atresia. Target sign: intussusception.", "Murphy: cholecystitis. **Reynolds pentad**: cholangitis.", "Obturator and psoas: retrocecal or pelvic appendicitis."], "p": 80}, {"t": 5748, "title": "GI bleed algorithm", "notes": ["Resuscitate (2 large IVs, type and cross). **NG aspirate or BUN:Cr** suggests upper.", "Upper: **endoscopy**. Lower: colonoscopy. Brisk and unstable: **CT angiogram** or angiography."], "p": 82}, {"t": 5820, "title": "Abdominal pain by location", "notes": ["RUQ: biliary, hepatitis. Epigastric: pancreatitis, ulcer, MI. RLQ: appendicitis, ectopic, torsion. LLQ: **diverticulitis**.", "Diffuse: **mesenteric ischemia**, obstruction, perforation, DKA."], "p": 83}, {"t": 5891, "title": "Aortic dissection", "notes": ["Tearing chest pain to the back. Type A (ascending): **surgery**. Type B: **beta blocker** (heart rate under 60, SBP under 120).", "Marfan, Ehlers-Danlos, hypertension, cocaine, bicuspid valve."], "p": 84}, {"t": 5962, "title": "Weird associations", "notes": ["Pulsatile mass + thrill after stabbing or dialysis access: **AV fistula** (high-output heart failure).", "Subclavian steal: **arm exercise causes dizziness**, BP difference between arms."], "p": 85}, {"t": 6104, "title": "Burns", "notes": ["**Parkland: 4 mL x kg x %TBSA**, half in first 8 h. Rule of 9s (second degree and deeper only).", "Inhalation: **intubate early**. CO: **carboxyhemoglobin**, 100% O2, hyperbaric.", "Burn patients: **PPI** (Curling ulcer). Electrical: ECG, rhabdo."], "p": 87}, {"t": 6246, "title": "Breast associations", "notes": ["Risk: early menarche, late menopause, nulliparity, estrogen, BRCA, obesity.", "Bloody discharge: **intraductal papilloma**. Young mobile mass: **fibroadenoma**.", "Cyst: **FNA**. Serous and resolves: stop. Bloody: biopsy. 40+ with a mass: **mammogram**, then biopsy even if negative."], "p": 89}, {"t": 6388, "title": "Hernias", "notes": ["Umbilical in kids: associated with **congenital hypothyroidism**, close by 4 to 5.", "Femoral: women, **below the inguinal ligament, medial to the vessels**, incarcerates.", "Incarcerated or strangulated: **surgery**."], "p": 91}, {"t": 6460, "title": "Small bowel obstruction", "notes": ["High-pitched tinkling sounds, prior appendectomy: **SBO (adhesions)**.", "**NPO, IV fluids, NG decompression**. Surgery if strangulation or no improvement."], "p": 92}, {"t": 6602, "title": "Postoperative fever: the 5 Ws", "notes": ["Wind: atelectasis day 1, pneumonia day 2 to 3. Water: **UTI day 3 to 5**. Walking: DVT day 5.", "Wound: **day 5 to 8**. Wonder drugs: any time (antibiotics, heparin)."], "p": 94}, {"t": 6673, "title": "Neurosurgical and trauma emergencies", "notes": ["High ICP: **Cushing triad** (hypertension, bradycardia, irregular breathing). Head up, mannitol, hyperventilation.", "Tetanus: clean wound, **toxoid if over 10 years**. Dirty: toxoid if over 5 years. **Unknown or under 3 doses: toxoid + immune globulin** for dirty wounds.", "Spinal cord: anterior cord (burst fracture, **posterior columns spared**), central cord (hyperextension, arms worse), Brown-Sequard (hemisection)."], "p": 95}, {"t": 6815, "title": "Urology and transplant triggers", "notes": ["Pelvic fracture + meatal blood: **retrograde urethrogram**.", "Best donor: **living related**. Hyperacute: preformed antibodies. Acute: T cells, reversible. Chronic: irreversible.", "Cyclosporine and tacrolimus: **nephrotoxicity**.", "Hypospadias and epispadias: **no circumcision** (foreskin for repair)."], "p": 97}, {"t": 6957, "title": "More triggers: ARDS, hip, eye", "notes": ["Post-op white-out lung, PCWP under 18: **ARDS**.", "Steroids or sickle cell + hip pain: **avascular necrosis** (MRI).", "Lumbar disc **L5 to S1**: decreased ankle jerk.", "Orbital cellulitis: proptosis, painful eye movements. Angle-closure glaucoma: emergency."], "p": 99}, {"t": 7100, "title": "Transfusion and electrolyte complications", "notes": ["**Massive transfusion: hypocalcemia** (citrate chelates calcium), hypothermia, coagulopathy.", "Trousseau and Chvostek, long QT. **IV calcium**."], "p": 101}, {"t": 7384, "title": "Esophageal triggers", "notes": ["Corkscrew, chest pain relieved by nitroglycerin: **diffuse esophageal spasm**.", "Long GERD or lye ingestion: **stricture**. Columnar cells: **Barrett** (surveillance).", "Solids and liquids, bird beak: **achalasia**. Solids then liquids + weight loss: cancer.", "Plummer-Vinson: **web + iron deficiency**. Schatzki ring."], "p": 105}, {"t": 7526, "title": "Post-op respiratory alkalosis", "notes": ["Tachypneic post-op patient with respiratory alkalosis and **pain**: **optimize analgesia** first.", "Do not jump to PE workup without supporting findings."], "p": 107}, {"t": 7668, "title": "Global review: drugs and peds surgery", "notes": ["Chemo vomiting: **ondansetron**. Opioid respiratory depression: **naloxone**.", "Post-op pyelonephritis: ceftriaxone. GI infections: **ciprofloxacin + metronidazole**.", "C diff: **oral vancomycin or fidaxomicin**. Hirschsprung: rectal biopsy. Intussusception: air enema."], "p": 109}, {"t": 7811, "title": "Global review: eyes and neuro", "notes": ["Contact lens + red eye: **Pseudomonas**, topical fluoroquinolone.", "Dendritic ulcer: **HSV keratitis**, acyclovir.", "**Cherry red spot**: central retinal artery occlusion. **Blood and thunder**: central retinal vein occlusion.", "Young woman, deficits in time and space, eye pain: **MS (optic neuritis)**."], "p": 111}, {"t": 7953, "title": "Global review: congenital heart, wounds, fluids", "notes": ["Down syndrome: **endocardial cushion defect**. Tetralogy: DiGeorge. Long VSD now cyanotic: **Eisenmenger**.", "Oliguria with catheter in place: **fluid challenge**. Pseudo-obstruction: **neostigmine**.", "Wound classes: clean (thyroid), clean-contaminated, **contaminated** (stab breaching peritoneum), **dirty** (abscess)."], "p": 113}, {"t": 8095, "title": "Global review: anorectal and liver", "notes": ["After splenic repair, epigastric and shoulder pain: **subphrenic abscess**.", "OCPs + liver mass: **hepatic adenoma**.", "Anal: fissure (pain + blood with stool), **abscess** (fluctuant, drain), fistula (Crohn), **pilonidal** (above gluteal cleft).", "**External hemorrhoids painful** (below dentate). Internal: painless bleeding. Anal cancer: squamous (HPV)."], "p": 115}], "pdf": "Divine%20Intervention%20Ep24.pdf"}];
